from pptx import Presentation

p = Presentation('/home/user/Desktop/38_1.pptx')

def find_first_textbox(shapes):
    for shape in shapes:
        if shape.shape_type == 6:
            result = find_first_textbox(shape.shapes)
            if result is not None:
                return result
        elif shape.has_text_frame and shape.text_frame.text.strip():
            return shape
    return None

slides = list(p.slides)
for n, idx in [(3, 2), (4, 3), (5, 4)]:
    sh = find_first_textbox(slides[idx].shapes)
    print(f"Slide {n}: text={sh.text_frame.text[:40]!r}")
    for pidx, para in enumerate(sh.text_frame.paragraphs):
        print(f"   para[{pidx}] alignment={para.alignment}")
